import{_ as a,o as d,c as e,a0 as r}from"./chunks/framework.DUAiDAGh.js";const b=JSON.parse('{"title":"代码评审产出文档 · 通用模板","description":"","frontmatter":{},"headers":[],"relativePath":"archive/notes/代码评审产出文档_通用模板.md","filePath":"archive/notes/代码评审产出文档_通用模板.md"}'),o={name:"archive/notes/代码评审产出文档_通用模板.md"};function i(h,t,l,s,n,p){return d(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="代码评审产出文档-·-通用模板" tabindex="-1">代码评审产出文档 · 通用模板 <a class="header-anchor" href="#代码评审产出文档-·-通用模板" aria-label="Permalink to &quot;代码评审产出文档 · 通用模板&quot;">​</a></h1><blockquote><p>说明：本模板为可复用骨架。换评审范围/换人时，只需替换三处——①「规定范围」、②「分级与修复计划」的责任划分、③「五步法逐条复核」的具体实例。其余骨架、表格列名、五步法结构原样复用。</p></blockquote><hr><h2 id="一、评审概况-信息表" tabindex="-1">一、评审概况（信息表） <a class="header-anchor" href="#一、评审概况-信息表" aria-label="Permalink to &quot;一、评审概况（信息表）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>课程 / 任务</td><td>【填写】</td></tr><tr><td>姓名 / 学号</td><td>【填写】</td></tr><tr><td>评审对象</td><td>【类名 / 模块 / 文件】</td></tr><tr><td>评审方法</td><td>【AI 扫描 + 人工复核 / 结对评审 / 走查】</td></tr><tr><td>规定范围</td><td>【本次评审关注的坏味道类型 / 维度 / 规则】</td></tr><tr><td>最小修复数</td><td>【minFix 计算规则与结果】</td></tr><tr><td>日期</td><td>【填写】</td></tr></tbody></table><hr><h2 id="二、评审依据-本次规定的标准" tabindex="-1">二、评审依据（本次规定的标准） <a class="header-anchor" href="#二、评审依据-本次规定的标准" aria-label="Permalink to &quot;二、评审依据（本次规定的标准）&quot;">​</a></h2><p>本次评审按【规定范围】执行，标准维度如下：</p><table tabindex="0"><thead><tr><th>维度编号</th><th>维度名称</th><th>判定依据</th></tr></thead><tbody><tr><td>D1</td><td>【维度1】</td><td>【说明】</td></tr><tr><td>D2</td><td>【维度2】</td><td>【说明】</td></tr><tr><td>D3</td><td>【维度3】</td><td>【说明】</td></tr><tr><td>D4</td><td>【维度4】</td><td>【说明】</td></tr><tr><td>D5</td><td>【维度5】</td><td>【说明】</td></tr></tbody></table><blockquote><p>注：如果当次没有「五维」要求，就把这一节换成当次给定的分类标准，例如「代码规范 / 性能 / 安全 / 可维护性」等。</p></blockquote><hr><h2 id="三、扫描总表" tabindex="-1">三、扫描总表 <a class="header-anchor" href="#三、扫描总表" aria-label="Permalink to &quot;三、扫描总表&quot;">​</a></h2><p>AI 扫描 + 人工复核后，共识别【N】个问题：</p><table tabindex="0"><thead><tr><th>序号</th><th>位置</th><th>类型</th><th>严重度</th><th>责任归属</th><th>依据标准</th></tr></thead><tbody><tr><td>①</td><td>【类.方法 / 行号】</td><td>【坏味道类型】</td><td>高/中/低</td><td>本人 / 遗留 / 不得修改</td><td>【对应维度】</td></tr><tr><td>②</td><td>…</td><td>…</td><td>…</td><td>…</td><td>…</td></tr><tr><td>③</td><td>…</td><td>…</td><td>…</td><td>…</td><td>…</td></tr></tbody></table><hr><h2 id="四、分级与修复计划" tabindex="-1">四、分级与修复计划 <a class="header-anchor" href="#四、分级与修复计划" aria-label="Permalink to &quot;四、分级与修复计划&quot;">​</a></h2><p>按本次规定范围，将问题分为三类：</p><table tabindex="0"><thead><tr><th>类别</th><th>说明</th><th>序号</th></tr></thead><tbody><tr><td>本人负责修复</td><td>【本次规定的主坏味道 / 次坏味道】</td><td>①②③</td></tr><tr><td>识别但保留为遗留</td><td>【本次不要求改的类型】</td><td>④⑤⑥⑦</td></tr><tr><td>不得修改区域</td><td>【题目/规范禁止改动部分】</td><td>—</td></tr></tbody></table><p><strong>修复目标：</strong> 至少修复【minFix】处本人负责的问题。</p><hr><h2 id="五、逐条复核-五步法" tabindex="-1">五、逐条复核（五步法） <a class="header-anchor" href="#五、逐条复核-五步法" aria-label="Permalink to &quot;五、逐条复核（五步法）&quot;">​</a></h2><p>对每个本人负责的问题，按以下五段式写：</p><h3 id="问题-1" tabindex="-1">问题 ① <a class="header-anchor" href="#问题-1" aria-label="Permalink to &quot;问题 ①&quot;">​</a></h3><ol><li><p><strong>问题定位</strong> 【哪个类 / 哪个方法 / 哪一行 / 哪段逻辑】</p></li><li><p><strong>问题描述</strong></p><ul><li>现象：【当前代码表现出的问题】</li><li>触发条件：【什么输入 / 什么场景会暴露】</li></ul></li><li><p><strong>依据标准</strong> 【对应本次规定的哪个维度 / 哪条规则】</p></li><li><p><strong>修复建议</strong> 【怎么改、改成什么样、用什么重构手法】</p></li><li><p><strong>验证方式</strong> 【跑哪条用例 / 看哪个断言 / 观察哪个输出】</p></li></ol><blockquote><p>问题 ②、③ … 同上结构重复即可。</p></blockquote><hr><h2 id="六、行为不变性说明-关键证明段" tabindex="-1">六、行为不变性说明（关键证明段） <a class="header-anchor" href="#六、行为不变性说明-关键证明段" aria-label="Permalink to &quot;六、行为不变性说明（关键证明段）&quot;">​</a></h2><p>重构前后需证明「行为契约未被破坏」。写法：</p><blockquote><p>传入【测试数据】→ 原逻辑输出【X】→ 重构后保留【关键闸门 / 判断条件】→ 输出仍为【X】→ 与断言 / 预期一致。</p></blockquote><p>如果当次没有断言，就写：</p><blockquote><p>重构仅改变【结构 / 命名 / 组织方式】，未改变【输入输出关系 / 业务判断条件 / 返回值】。</p></blockquote><hr><h2 id="七、修复统计与归档" tabindex="-1">七、修复统计与归档 <a class="header-anchor" href="#七、修复统计与归档" aria-label="Permalink to &quot;七、修复统计与归档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>值</th></tr></thead><tbody><tr><td>识别总数</td><td>【N】</td></tr><tr><td>已修复</td><td>【M】</td></tr><tr><td>遗留</td><td>【N - M】</td></tr><tr><td>是否满足 minFix</td><td>【是 / 否】</td></tr></tbody></table><p><strong>归档行（机器可校验）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REVIEW|识别总数|已修复|遗留</span></span></code></pre></div><hr><h2 id="八、重构后代码快照-可选" tabindex="-1">八、重构后代码快照（可选） <a class="header-anchor" href="#八、重构后代码快照-可选" aria-label="Permalink to &quot;八、重构后代码快照（可选）&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 修复①：【说明】</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 修复②：【说明】</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 修复③：【说明】</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">【重构后的方法代码】</span></span></code></pre></div><hr><h2 id="套用口诀" tabindex="-1">套用口诀 <a class="header-anchor" href="#套用口诀" aria-label="Permalink to &quot;套用口诀&quot;">​</a></h2><blockquote><p><strong>信息表定身份 → 标准定维度 → 总表列问题 → 分级切责任 → 五步法逐条写 → 数字走查证行为不变 → REVIEW 行收尾。</strong></p></blockquote><p>换评审范围时，只需要替换三处：</p><ol><li><strong>「规定范围」</strong>：换成当次要求的坏味道类型或维度；</li><li><strong>「分级与修复计划」</strong>：按当次规则重新划分本人 / 遗留 / 不得修改；</li><li><strong>「五步法逐条复核」</strong>：把具体位置、现象、依据换成当次实例。</li></ol><p>其余骨架、表格列名、五步法结构都可以原样复用。</p>`,45)])])}const u=a(o,[["render",i]]);export{b as __pageData,u as default};
